create table public.inventory_movements (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id), location_id uuid not null, variant_id uuid not null, quantity_delta integer not null check(quantity_delta <> 0), reason text not null, reference text, actor_user_id uuid references public.users(id) on delete set null, created_at timestamptz not null default now(), foreign key(store_id,location_id) references public.inventory_locations(store_id,id), foreign key(store_id,variant_id) references public.product_variants(store_id,id));
create index idx_inventory_movements_variant on public.inventory_movements(store_id,variant_id,created_at desc);
